"""Show recorded token usage for a Codex session and its Gemini workers."""

import argparse
import json
import os
from pathlib import Path
import sys

ROOT = Path.home() / ".codex"
SESSIONS = ROOT / "sessions"
LEDGER = ROOT / "gemini-worker-sessions.jsonl"
FIELDS = ("input_tokens", "cached_input_tokens", "output_tokens", "reasoning_output_tokens", "total_tokens")


def trace_for(session_id):
    return next(SESSIONS.rglob(f"*{session_id}.jsonl"), None)


def trace_usage(session_id):
    path = trace_for(session_id)
    if path is None:
        return None, None, None
    usage = None
    model = provider = None
    with path.open() as stream:
        for line in stream:
            try:
                entry = json.loads(line)
            except json.JSONDecodeError:
                continue
            payload = entry.get("payload", {})
            if entry.get("type") == "session_meta":
                provider = payload.get("model_provider", provider)
            elif entry.get("type") == "turn_context":
                model = payload.get("model", model)
            elif entry.get("type") == "event_msg" and payload.get("type") == "token_count":
                usage = (payload.get("info") or {}).get("total_token_usage", usage)
    return usage, model, provider


def fmt(usage):
    if usage is None:
        return "usage pending/unavailable"
    return (f"input {usage.get('input_tokens', 0):,} "
            f"(cached {usage.get('cached_input_tokens', 0):,}), "
            f"output {usage.get('output_tokens', 0):,} "
            f"(reasoning {usage.get('reasoning_output_tokens', 0):,}), "
            f"total {usage.get('total_tokens', 0):,}")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("session_id", nargs="?", help="Parent session ID; defaults to CODEX_SESSION_ID")
    parser.add_argument("--latest", action="store_true", help="Use the latest saved session")
    args = parser.parse_args()
    session_id = args.session_id or os.environ.get("CODEX_SESSION_ID") or os.environ.get("CODEX_THREAD_ID")
    if args.latest:
        child_ids = set()
        if LEDGER.exists():
            for line in LEDGER.read_text().splitlines():
                try:
                    child_ids.add(json.loads(line)["worker_session_id"])
                except (json.JSONDecodeError, KeyError):
                    continue
        paths = [p for p in SESSIONS.rglob("rollout-*.jsonl")
                 if "-".join(p.stem.rsplit("-", 5)[-5:]) not in child_ids]
        if not paths:
            parser.error("no saved primary sessions found")
        session_id = "-".join(max(paths, key=lambda p: p.name).stem.rsplit("-", 5)[-5:])
    if not session_id:
        parser.error("provide a session ID or run from inside a Codex session")
    usage, model, provider = trace_usage(session_id)
    if trace_for(session_id) is None:
        parser.error(f"session trace not found: {session_id}")
    print(f"Session {session_id}")
    print(f"Main ({model or '?'}/{provider or '?'}): {fmt(usage)}")
    workers = []
    if LEDGER.exists():
        for line in LEDGER.read_text().splitlines():
            try:
                record = json.loads(line)
            except json.JSONDecodeError:
                continue
            if record.get("parent_session_id") == session_id:
                workers.append(record)
    totals = {field: 0 for field in FIELDS}
    missing = 0
    for record in workers:
        child_id = record["worker_session_id"]
        child_usage, child_model, _ = trace_usage(child_id)
        print(f"Gemini worker {child_id} ({child_model or record.get('model', '?')}): {fmt(child_usage)}")
        if child_usage is None:
            missing += 1
        else:
            for field in FIELDS:
                totals[field] += child_usage.get(field, 0)
    print(f"Gemini workers ({len(workers)}): {fmt(totals) if workers and not missing else ('none' if not workers else fmt(totals) + f'; {missing} pending')}")
    if usage is not None and not missing:
        combined = {field: usage.get(field, 0) + totals[field] for field in FIELDS}
        print(f"Combined: {fmt(combined)}")
    elif workers:
        print("Combined: pending")
    print("Recorded tokens only; this is not a billing amount.")


if __name__ == "__main__":
